script:
def walk(path, acc):
    for entry in repo.list(path):
        full = (path.rstrip("/") + "/" + entry) if path != "." else entry
        if entry.endswith("/"):
            walk(full, acc)
        else:
            acc.append(full)
    return acc

all_files = walk("src", [])
all_docs = walk("docs", [])
out = {}
for p in all_files + all_docs:
    out[p] = repr(repo.read(p))
return {"src_files": all_files, "docs_files": all_docs, "contents": out}

